{
  "query": "query Channel($slug: String!) {\n  channel(slug: $slug) { id slug currencyCode }\n}",
  "variables": {
    "slug": "{{ _.channel }}"
  }
}

resources.preRequestScript:
insomnia.environment.set('authorization', '');

const rawReq = {
    url: insomnia.environment.get('url'),
    method: 'POST',
    header: {
        'Content-Type': 'application/json',
    },
    body: {
        mode: 'raw',
        raw: `{\"operationName\":\"loginWithoutDetails\",\"variables\":{\"email\":\"${insomnia.environment.get('username')}\",\"password\":\"${insomnia.environment.get('password')}\"},\"query\":\"fragment AccountErrorFragment on AccountError {\\n  code\\n  field\\n  message\\n  __typename\\n}\\n\\nfragment UserBaseFragment on User {\\n  id\\n  email\\n  firstName\\n  lastName\\n  isStaff\\n  userPermissions {\\n    code\\n    name\\n    __typename\\n  }\\n  __typename\\n}\\n\\nmutation loginWithoutDetails($email: String!, $password: String!) {\\n  tokenCreate(email: $email, password: $password) {\\n    refreshToken\\n    token\\n    errors {\\n      ...AccountErrorFragment\\n      __typename\\n    }\\n    user {\\n      ...UserBaseFragment\\n      __typename\\n    }\\n    __typename\\n  }\\n}\\n\"}`,
    },
};

const resp = await new Promise((resolve, reject) => {
    insomnia.sendRequest(
        rawReq,
        (err, resp) => {
            if (err != null) {
                reject(err);
            } else {
                resolve(resp);
            }
        }
    );
});

insomnia.environment.set('authorization', resp.json().data.tokenCreate.token);

