{
  "query": "query PickVariant($channel: String!) {
  productVariants(first: 1, channel: $channel, where: { stockAvailability: IN_STOCK }) {
    edges {
      node {
        id
        name
        product { id name }
        channelListings {
          id
          channel { slug }
          price { amount currency }
          prices { id }
        }
      }
    }
  }
}",
  "variables": {
    "channel": "{{ _.channel }}"
  }
}

