resources.afterResponseScript:
const data = insomnia.response.json().data;
const node = data.productVariants.edges[0].node;
insomnia.environment.set('variantId', node.id);
insomnia.environment.set('productId', node.product.id);
const channel = insomnia.environment.get('channel');
const listing = node.channelListings.find((l) => l.channel.slug === channel);
insomnia.environment.set('listingId', listing.id);
insomnia.environment.set('listingPrice', listing.price.amount);
insomnia.environment.set('scopedPrice', (Math.round(listing.price.amount * 80) / 100).toFixed(2));
insomnia.environment.set('windowPrice', (Math.round(listing.price.amount * 90) / 100).toFixed(2));

