  "query": "mutation CreateScopedPrice($input: VariantChannelListingPriceCreateInput!) {
  variantChannelListingPriceCreate(input: $input) {
    variantChannelListingPrice { ...ScopedPriceFields }
    errors { field code message customerTypes customerAttributeValues }
  }
